def validate(m):
 assert len(m['heroes'])==34
 source=json.loads((ROOT/'docs/design/hero-abilities-34.json').read_text())
 assert {h['id'] for h in m['heroes']}=={h['id'] for h in source['heroes']}
 for h in m['heroes']:
  ps={p['id'] for p in h['bodyPoses']}; ss={s['id'] for s in h['sequences']}; fs={f['id'] for f in h['fxSequences']}
  assert len(ps)==len(h['bodyPoses']); assert len(ss)==len(h['sequences']); assert len(fs)==len(h['fxSequences'])
  assert all(p['localAnchor']==[96,132] and not p['rootEmbedded'] for p in h['bodyPoses'])
  for s in h['sequences']:
   assert s['frameCount']==len(s['frames'])
   assert all(f['pose'] in ps and f['durationMs']>0 for f in s['frames'])
   assert s['durationMs']==sum(f['durationMs'] for f in s['frames'])
   # Latched-root failure sequences are relative to that location; all other ready endings are exact origin.
   if s['endState']=='ready' or s['endState'].startswith('ready '): assert s['frames'][-1]['rootX']==0
   assert all(f['rootY']==0 for f in s['frames'])
  assert len(h['cardMappings'])==18
  sh=next(a for a in source['heroes'] if a['id']==h['id'])
  assert [c['name'] for c in h['cardMappings'][:12]]==[c['name'] for c in sh['cards']]
  assert [c['sourceEffect'] for c in h['cardMappings'][:12]]==[c['effect'] for c in sh['cards']]
  assert [c['sourceEffect'] for c in h['cardMappings'][12:]]==[c['effect'] for c in source['shared'][h['family']]]
  for c in h['cardMappings']:
   if c['kind']=='Passive': assert c['activationActions']==0 and c['bodySequence'] is None and c['optionalStateFx'] in fs
   else: assert c['bodySequence'] in ss and c['fxSequence'] in fs and c['activationActions']==1
  assert all(v in ss for v in h['coreMappings'].values())
  assert all(f['pose'] in ps for f in h['interruptionReturn']['frames'])
  assert [f['remainingFraction'] for f in h['interruptionReturn']['frames']]==[1,0.5,0]
  assert all(v in ss for c in h['cardMappings'] for v in c.get('bodySequenceBranches',{}).values())
  assert {g['job'] for g in h['gatheringMappings']}=={'mining','woodcutting','foraging','hunting'}
  for g in h['gatheringMappings']: assert all(g[k] in ss for k in ['stowCombat','equipTool','toolLoop','handFallback','stowTool','retrieveCombat'])
  c=h['counts']; assert c['bodyPoses']==len(ps); assert c['timelineFrames']==sum(s['frameCount'] for s in h['sequences']); assert c['fxFrames']==sum(len(f['frames']) for f in h['fxSequences'])
  assert all(f['frameCount']==len(f['frames']) for f in h['fxSequences'])
  frameids=[r['id'] for f in h['fxSequences'] for r in f['frames']]; assert len(frameids)==len(set(frameids))
  assert all(i in set(frameids) for f in h['fxSequences'] for layer in f['layers'] for i in layer['frameIds'])
 for k in ['bodyPoses','timelineFrames','fxFrames','sequences','fxSequences']: assert m['totals'][k]==sum(h['counts'][k] for h in m['heroes'])
 return f"34 heroes, 408 signatures, 204 shared mappings; all references, four gathering branches, passive zero-actions and totals reconcile. {m['totals']['bodyPoses']} body poses / {m['totals']['timelineFrames']} timeline keys / {m['totals']['fxFrames']} distinct FX frames."

def hero_md(h):
 c=h['counts']; short=lambda x:x.replace(h['id']+'--','')
 lines=[f"# {h['name']}: complete animation proposal",'',f"Planning only. {h['contactClassification']}; basic Attack type: {h['basicAttackType']}. Expanded cards/equipment remain proposals; concept approval is not pose approval.",'',f"**Count:** {c['bodyPoses']} distinct body poses; {c['timelineFrames']} body timeline keys across {c['sequences']} sequences; {c['fxFrames']} distinct separate FX frames across {c['fxSequences']} FX sequences. Nine active signatures + three passives + five active class tools + one class passive. Passives require zero activation poses/actions.",'',f"Concept identity: `{h['conceptSource']['file']}` (SHA256 `{h['conceptSource']['sha256']}`). Remaining registry notes: {'; '.join(h['conceptSource']['remaining_notes']) or 'none'}. Keep the signed-off whole design; profile notes below explain kit intent and never override the approved pixels.",'',h['profile']['identity'],'',f"Equipment: {h['equipment']}.",f"Motion identity: {h['motionSignature']}.",'',h['gearContract']['continuity'],h['gearContract']['twoHandRule'],h['gearContract']['cloth'],'',h['gearContract']['productionSocketCoordinates'],'','## Core, anchors and transitions','', 'Authored facing right. Local body canvas 224×192, foot anchor (96,132); actual boots end on row 131. Root motion is separate. Grip/focus/offhand/tome/lantern sockets move with the actual pose; keep the original concept side and supported attachments. No compulsory walk, jump or staff teleport. No new gameplay from motion.']
 if h['counts']['dashContactOffsetPx']: lines +=['',f"Melee contact uses one dash envelope: 0 → {c['dashContactOffsetPx']//2} → {c['dashContactOffsetPx']} → {c['dashContactOffsetPx']//2} → 0 px. Every listed contact sequence records the full exact return. Utility/casts stay planted. On interruption latch the current world root, retract visibly and return continuously if alive; death falls at that latched location and never snaps home."]
 else: lines +=['','Spell/bow attacks stay at rootX=0. Manual Dodge has a small 0→−12→−6→0 lean. Pip and other casters have no required walking pose. Interruption/death latch the current world position.']
 lines+=['','Interruption return contract: '+json.dumps(h['interruptionReturn'],ensure_ascii=False), '','Core mappings: '+', '.join(f'{k} → `{short(v)}`' for k,v in h['coreMappings'].items()),'','Timing values below are presentation targets. Charged wind-ups hold 80–700ms for one ring/grade, then commit release and recoil/recovery. Hold time adds no pose. Reduced motion preserves event order and static state glyphs; do not retune input windows.','',h['gatheringContract'],'','For each gathering job: `stow-combat` → job equip (if tool) → tool loop or hand loop → job stow (if tool) → `retrieve-combat`. Camp uses the same visible combat stow/retrieve. Each tool has separate four-key draw and four-key put-away; no popping tool or unarmed combat.','', '## Every signature and shared class card','']
 for card in h['cardMappings']:
  lines +=[f"### {card.get('displayName',card['name'])} ({card['scope']}, {card['kind']})",'',card['sourceEffect'],'']
  if card['kind']=='Passive': lines +=[f"Zero activation actions or added body poses. {card['reuse']}. Optional state FX: `{short(card['optionalStateFx'])}`; exact eligibility and clearing only."]
  else: lines +=[f"Body sequence `{short(card['bodySequence'])}`, geometry {card['bodyGeometry']}; FX `{short(card['fxSequence'])}`. Start: {card['start']}. End: {card['end']}. Event: {card['event']}. {'One timed charged hold before earned release.' if card['timed'] else 'Deliberate untimed anticipation before release and recovery.'}"]
  if card.get('bodySequenceBranches'): lines +=['Body branch sequences: '+', '.join(k+' → `'+short(v)+'`' for k,v in card['bodySequenceBranches'].items())+'. Same single action budget and exact origin return.']
 lines+=['','## Production order','']
 for stage in h['productionStages']: lines +=[f"Stage {stage['stage']}: {stage['name']}. {stage.get('distinctBodyPoses','remaining')} distinct body poses; {stage.get('timelineFrames','remaining')} timeline keys. {stage['scope']}"]
 lines+=['','## Distinct body pose inventory','', '| Pose ID | Purpose and explicit drawing | Equipment |','|---|---|---|']
 for p in h['bodyPoses']: lines +=[f"| `{short(p['id'])}` | {p['purpose']}: {p['description']} | {p['equipment']} |"]
 lines+=['','## Body sequence keys, event and exact root','', 'Each row is one displayed key occurrence. A repeated ID reuses the same distinct pose. Local foot anchor remains (96,132) on every row. Start/end equipment states are written per sequence; full drawing description is in the pose inventory.']
 lookup={p['id']:p for p in h['bodyPoses']}
 for s in h['sequences']:
  lines +=['',f"### `{short(s['id'])}` — {s['purpose']}",'',f"{s['frameCount']} timeline keys / {s['durationMs']}ms. Start: {s['startState']}. End: {s['endState']}. Hold: {s['hold']}.",'','| Key | Pose | Hold ms | Root X,Y px | Event |','|---|---|---:|---|---|']
  for f in s['frames']: lines +=[f"| {f['frame']} | `{short(f['pose'])}` | {f['durationMs']} | {f['rootX']},0 | {f['event'] or 'continue visible motion'} |"]
 lines+=['','## Separate FX sheets: exact frame descriptions','', 'Each layer is artist-authored matching pixel art. Wide impact, arrows and status contours never shrink the body. The source card above remains authoritative: a mentioned prerequisite/consumed status is never silently a new application.']
 for f in h['fxSequences']:
  lines +=['',f"### `{short(f['id'])}` — {f['cardName']}",'',f"{f['frameCount']} distinct FX frames. {f['branches']} {f['hold']}",f['releaseContact']]
  if f.get('deferredOrDerived'): lines +=[f['deferredOrDerived']]
  if f['layers']: lines +=['Independent layer tracks: '+ '; '.join(layer['name']+' → '+','.join('`'+short(k)+'`' for k in layer['frameIds'])+' ('+layer['startEvent']+' → '+layer['endEvent']+')' for layer in f['layers'])+'. Shared frame IDs reference the counted reusable module/state sheet.']
  lines +=['','| FX frame ID | Drawing and phase | Hold ms | Socket |','|---|---|---:|---|']
  for r in f['frames']: lines +=[f"| `{short(r['id'])}` | {r['description']} | {r['durationMs']} | {r['anchor']} |"]
 return '\n'.join(lines)+'\n'

def write(m):
 OUT.mkdir(parents=True,exist_ok=True)
 (OUT/'manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
 briefs=[]
 for h in m['heroes']:
  content=hero_md(h); filename=slug(h['name'])+'.md'; (OUT/filename).write_text(content); briefs.append((h,filename,content))
 rows=['| Hero | Contact | Distinct body poses | Timeline keys | Separate FX frames |','|---|---|---:|---:|---:|']
 for h,filename,_ in briefs:
  c=h['counts']; rows.append(f"| [{h['name']}]({filename}) | {h['contactClassification']} | {c['bodyPoses']} | {c['timelineFrames']} | {c['fxFrames']} |")
 t=m['totals']; rows.append(f"| **Total: 34** | | **{t['bodyPoses']}** | **{t['timelineFrames']}** | **{t['fxFrames']}** |")
 intro=['# Full 34-hero animation planning superset','','Planning proposal only. No images generated, pose packs modified, gates run, approvals claimed or runtime integrated. Uses the 34 selected kits and the official owner-approved concept registry at base `'+m['baseCommit']+'`. Owner-approved concept artwork establishes appearance, not approval of these body or FX sequences. Revised equipment/categories and nine-active/three-passive kits remain proposals.','',f"**{t['bodyPoses']} distinct body poses, {t['timelineFrames']} body timeline keys, {t['fxFrames']} separate FX frames.** Counts include 408 signature cards, 204 shared class mappings, ten core states per hero, all four live gathering jobs with optional tool and no-tool branches, visible equipment stow/retrieve, victory, camp and interruption handling.",'',t['historicalReconciliation'],'','Body IDs describe future artist workload. None is asserted to be an approved pose. Repeated IDs are deliberately reusable keys; separate timing variants do not create additional drawings. State FX and passives are counted separately. Passives add zero activation actions. The hand fallback sheets are distinct drawings because combat/gather tools must be visibly secured. No pose named throw is included because no selected kit throws held equipment. No mage needs walking. No proposed subclass/Hallowed expansion is counted without a complete approved visual contract.','','Open [offline count and frame viewer](index.html). It has no network requests, images or runtime links. [manifest.json](manifest.json) is the authoritative structured plan; each hero brief expands its exact frame and card records. Generator: `python tools/hero-animation-plan.py --write`; validation: `python tools/hero-animation-plan.py --check`.','', '## Shared contracts','']
 for k,v in m['contracts'].items(): intro +=[f"- **{k}:** {json.dumps(v,ensure_ascii=False) if not isinstance(v,str) else v}"]
 intro +=['','## Reconciled per-hero counts','']+rows+['','## Coverage and limits','','The generator validates 34 exact kit IDs, all 12 signature and six class-card names/effects per hero, every referenced pose/sequence/FX ID, four live gathering jobs with draw/stow/retrieve and no-tool alternatives, passive zero-action records, durations, grounded local anchors, root returns and summed counts. It preserves exact source-effect text and hashes. This is a structural planning check, not image/anatomy review or game balance validation. Numerical grip sockets and production source kits must be measured/built only in a later authorized art task.','', 'The only discovered source-v1 hero kit is the isolated Pip real-art test under `art/pose-lock-tests/pip`, read for its continuity/anchor contract. Its registered free-hand pose remains pending review and does not approve these plans. Future pose production must obey source kit, accepted-parent/mask edit, gate, register, verify and audit; only the owner approves. No gate threshold or equipment rule is waived.','', 'The underlying data spells Ragna’s older direct effects “poison” in places; the current kit contract maps direct witchlight to existing holy with Venom separate. Flint uses holy-electric visual wording, not a lightning damage/resistance type. Inga’s physical basic Attack uses held-staff contact; her other spells remain the written type. Corvin, Cass and Isolde are melee Rangers, never given bows by a class template.','', 'No full game build/check is claimed by this planning generator. The coordinating chat runs repository-wide checks. No runtime, economy, save, deployment, approved art or embedded modules changed.']
 (OUT/'README.md').write_text('\n'.join(intro)+'\n')
 tab=''.join(f'<tr data-hero="{html.escape(h["name"].lower())}"><td><a href="#{h["id"]}">{html.escape(h["name"])}</a></td><td>{h["contactClassification"]}</td><td>{h["counts"]["bodyPoses"]}</td><td>{h["counts"]["timelineFrames"]}</td><td>{h["counts"]["fxFrames"]}</td></tr>' for h,_,_ in briefs)
 details=''.join(f'<details id="{h["id"]}" data-hero="{html.escape(h["name"].lower())}"><summary>{html.escape(h["name"])} — {h["counts"]["bodyPoses"]} body / {h["counts"]["timelineFrames"]} keys / {h["counts"]["fxFrames"]} FX</summary><pre>{html.escape(content)}</pre></details>' for h,_,content in briefs)
 page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lanternfall — all 34 hero animation plans</title><style>body{{background:#191724;color:#eee8da;font:16px system-ui;margin:0 auto;padding:24px;max-width:1400px}}a{{color:#e8c77d}}table{{width:100%;border-collapse:collapse}}th,td{{border-bottom:1px solid #57505f;text-align:left;padding:9px}}input{{font:inherit;width:90%;padding:10px;background:#302c39;color:#fff;border:1px solid #8e8198}}details{{margin:12px 0;border:1px solid #57505f;padding:10px}}summary{{cursor:pointer}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.65 ui-monospace,monospace}}.totals{{font-size:22px}}[hidden]{{display:none}}@media(max-width:650px){{body{{padding:10px}}td,th{{padding:4px;font-size:12px}}}}</style><h1>34 heroes: complete animation planning superset</h1><p>Planning only. No artwork generated or integrated. Concept approval is separate from pose approval. All displayed frame descriptions are contained in this file.</p><p class="totals">{t['bodyPoses']} distinct body poses · {t['timelineFrames']} body timeline keys · {t['fxFrames']} separate FX frames</p><p>238 was the earlier Pip per-hero animation-frame estimate. This refines the full scope into distinct body poses, reused body timeline keys and separate FX frames; those categories cannot be equated. The expanded scope includes anticipation, charged hold, earned release, recoil, recovery, defence, failure, social states, equipment transitions and all four gathering jobs in tool/no-tool variants. Passives activate zero body actions. Melee includes Corvin, Cass, Isolde and Inga’s staff contact. Pip does not require a walk.</p><p>Root motion stays separate from local 224×192 cells at (96,132). Every normal contact dash returns to root X=0. Hurt/death latch the current world root and cannot snap home. Timings are presentation targets, not gameplay tuning. Gear sockets await measurement from future locked poses.</p><label>Filter heroes <input id="search" type="search" placeholder="Hero name" aria-label="Filter heroes"></label><table><thead><tr><th>Hero</th><th>Contact</th><th>Distinct body</th><th>Timeline keys</th><th>Separate FX</th></tr></thead><tbody>{tab}<tr><th>Total</th><td>34 heroes</td><th>{t['bodyPoses']}</th><th>{t['timelineFrames']}</th><th>{t['fxFrames']}</th></tr></tbody></table>{details}<script>const q=document.querySelector('#search');q.addEventListener('input',()=>{{const value=q.value.toLowerCase();document.querySelectorAll('[data-hero]').forEach(n=>n.hidden=!n.dataset.hero.includes(value));}});document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{{document.getElementById(a.hash.slice(1)).open=true;}}));</script></html>'''
 (OUT/'index.html').write_text(page)

def main():
 ap=argparse.ArgumentParser(); ap.add_argument('--write',action='store_true');ap.add_argument('--check',action='store_true');args=ap.parse_args()
 m=build(); message=validate(m)
 if args.write: write(m)
 if args.check:
  saved=json.loads((OUT/'manifest.json').read_text()); assert saved==m,'generated manifest drift';validate(saved)
  for h in m['heroes']: assert (OUT/(slug(h['name'])+'.md')).read_text()==hero_md(h),'hero brief drift'
 print(message)
if __name__=='__main__': main()
